// markAnchor is a skill row's id: the list it's in (place) and the skill,
// so marking it comes back to it there.
func markAnchor(place string, m MarkView) string {
	h := fnv.New32a()
	h.Write([]byte(m.Skill + "\x00" + m.Club + "\x00" + m.Item))
	return fmt.Sprintf("mark-%s-%08x", place, h.Sum32())
}

